package com.rpsbattle.tournament.coding;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.rpsbattle.auth.AuthException;
import com.rpsbattle.tournament.domain.*;
import jakarta.persistence.*;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

@Repository
public class FinalValidationStore {
 @Transactional public void suspendForExtension(UUID tournament){for(var f:db.createQuery("select f from FinalValidation f where f.tournamentId=:t",FinalValidation.class).setParameter("t",tournament).getResultList()){var entries=history(f);entries.add(Map.of("versionId",f.versionId.toString(),"status","TIMELINE_EXTENDED","reason","New audited coding window","emergencyDeadline",Objects.toString(f.emergencyDeadline,"")));f.historyJson=encode(entries);if(Set.of("QUEUED","RUNNING").contains(f.status)){f.status="INFRA_ERROR";f.reason="TIMELINE_EXTENDED";f.finishedAt=clock.instant();}if(f.appliedAt==null)f.appliedAt=clock.instant();f.emergencyOpenAt=null;f.emergencyDeadline=null;f.emergencyActor=null;f.emergencyReason=null;}}
 @PersistenceContext EntityManager db;
 private final ObjectMapper json;private final Clock clock;
 @org.springframework.beans.factory.annotation.Value("${rps.coding.queue-capacity:200}") int capacity=200;
 public FinalValidationStore(ObjectMapper json,Clock clock){this.json=json;this.clock=clock;}
 public static final List<String> STAGES=List.of("BUILD","PROTOCOL","TIMEOUT","RESOURCE","LEGAL_ACTION","HIDDEN_TESTS","TOURNAMENT_TESTS","ARTIFACT_HASH");
 static Map<String,String> emptySteps(){var steps=new LinkedHashMap<String,String>();STAGES.forEach(s->steps.put(s,"PENDING"));return steps;}
 String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception invalid){throw new IllegalStateException(invalid);}}
 Map<String,String> steps(FinalValidation f){try{return json.readValue(f.stepsJson,new TypeReference<LinkedHashMap<String,String>>(){});}catch(Exception invalid){throw new IllegalStateException(invalid);}}
 List<Map<String,Object>> history(FinalValidation f){try{return json.readValue(f.historyJson,new TypeReference<ArrayList<Map<String,Object>>>(){});}catch(Exception invalid){throw new IllegalStateException(invalid);}}
 public record View(UUID id,UUID userId,String displayName,String status,String reason,String failurePolicy,UUID originalVersionId,UUID versionId,int version,String language,String sourceHash,String artifactHash,Map<String,String> steps,List<Map<String,Object>> history,Instant createdAt,Instant finishedAt,boolean applied,Instant emergencyDeadline,boolean canRetry,boolean canGrantEmergency){}
 private boolean superseded(FinalValidation f){return history(f).stream().anyMatch(e->"TIMELINE_EXTENDED".equals(e.get("status")));}
 private View view(FinalValidation f){var v=db.find(CodeVersion.class,f.versionId);var w=db.find(CodeWorkspace.class,v.workspaceId);var original=db.find(CodingFreeze.class,f.freezeId);String status=f.emergencyDeadline!=null&&clock.instant().isBefore(f.emergencyDeadline)?"EMERGENCY_OPEN":f.status;String displayName=db.createNativeQuery("select display_name from tournament_timeline_registrations where tournament_id=:t and user_id=:u",String.class).setParameter("t",f.tournamentId).setParameter("u",f.userId).getResultStream().findFirst().map(Object::toString).orElse("Participant").toString();return new View(f.id,f.userId,displayName,status,f.reason,f.failurePolicy,original.versionId,v.id,v.number,w.language,f.sourceHash,f.artifactHash,Map.copyOf(steps(f)),List.copyOf(history(f)),f.createdAt,f.finishedAt,f.appliedAt!=null,f.emergencyDeadline,f.status.equals("INFRA_ERROR")&&!superseded(f),!superseded(f)&&f.status.equals("FAILED")&&f.appliedAt!=null&&f.failurePolicy.equals("ALLOW_EMERGENCY_RESUBMISSION")&&f.emergencyDeadline==null&&emergencyCutoff(f.tournamentId.toString(),f.userId)==null);}
 private FinalValidation own(UUID t,UUID u,Instant cutoff){return db.createQuery("select f from FinalValidation f,CodingFreeze c where f.freezeId=c.id and f.tournamentId=:t and f.userId=:u and c.codingCloseAt=:cutoff",FinalValidation.class).setParameter("t",t).setParameter("u",u).setParameter("cutoff",cutoff).getResultStream().findFirst().orElse(null);}
 @Transactional(readOnly=true) public View mine(String t,UUID user,Instant cutoff){var f=own(UUID.fromString(t),user,cutoff);return f==null?null:view(f);}
 @Transactional(readOnly=true) public View detail(String t,UUID id){var f=require(t,id);return view(f);}
 private FinalValidation require(String t,UUID id){var f=db.find(FinalValidation.class,id);if(f==null||!f.tournamentId.toString().equals(t))throw new AuthException("FINAL_VALIDATION_NOT_FOUND",404);return f;}
 @Transactional(readOnly=true) public List<View> page(String t,int page){return db.createQuery("select f from FinalValidation f where f.tournamentId=:t order by f.createdAt desc,f.id",FinalValidation.class).setParameter("t",UUID.fromString(t)).setFirstResult(page*25).setMaxResults(25).getResultStream().map(this::view).toList();}
 @Transactional(readOnly=true) public List<View> page(String t,int page,String status){
  if(status==null)return page(t,page);
  String state=status.equals("EMERGENCY_OPEN")?"f.emergencyDeadline>:now":"f.status=:status and (f.emergencyDeadline is null or f.emergencyDeadline<=:now)";
  var q=db.createQuery("select f from FinalValidation f,CodingFreeze c where f.freezeId=c.id and f.tournamentId=:t and f.historyJson not like '%TIMELINE_EXTENDED%' and not exists(select n.id from CodingFreeze n where n.tournamentId=f.tournamentId and n.userId=f.userId and n.codingCloseAt>c.codingCloseAt) and "+state+" order by f.createdAt desc,f.id",FinalValidation.class).setParameter("t",UUID.fromString(t)).setParameter("now",clock.instant());if(!status.equals("EMERGENCY_OPEN"))q.setParameter("status",status);
  return q.setFirstResult(page*25).setMaxResults(25).getResultStream().map(this::view).toList();
 }
 @Transactional(readOnly=true) public List<UUID> pendingFreezes(String t,int limit){return db.createQuery("select c.id from CodingFreeze c where c.tournamentId=:t and c.decision<>'MISSING' and not exists(select f.id from FinalValidation f where f.freezeId=c.id) and not exists(select newer.id from CodingFreeze newer where newer.tournamentId=c.tournamentId and newer.userId=c.userId and newer.codingCloseAt>c.codingCloseAt) order by c.codingCloseAt,c.id",UUID.class).setParameter("t",UUID.fromString(t)).setMaxResults(limit).getResultList();}
 private void admit(){db.createNativeQuery("select id from coding_queue_guard where id=1 for update").getSingleResult();if(db.createQuery("select count(j) from CodingJob j where j.status in ('QUEUED','RUNNING')",Long.class).getSingleResult()>=capacity)throw new AuthException("WORKSPACE_QUEUE_FULL",429);}
 private void enqueue(FinalValidation f){admit();var v=db.find(CodeVersion.class,f.versionId);var j=new CodingJob();j.id=UUID.randomUUID();j.workspaceId=v.workspaceId;j.versionId=v.id;j.kind="VALIDATE";j.finalValidationId=f.id;j.status="QUEUED";j.createdAt=clock.instant();j.hiddenRequired=true;db.persist(j);db.flush();f.jobId=j.id;f.status="QUEUED";f.reason=null;f.finishedAt=null;f.appliedAt=null;f.stepsJson=encode(emptySteps());}
 @Transactional public void create(Tournament t,UUID freezeId){var c=db.find(CodingFreeze.class,freezeId,LockModeType.PESSIMISTIC_WRITE);if(c==null||!c.tournamentId.toString().equals(t.id)||c.decision.equals("MISSING"))return;if(own(c.tournamentId,c.userId,c.codingCloseAt)!=null)return;Instant now=clock.instant();if(now.isBefore(t.timeline.validationStartAt())||now.isBefore(c.codingCloseAt))throw new AuthException("VALIDATION_NOT_OPEN",409);var f=new FinalValidation();f.id=UUID.randomUUID();f.freezeId=c.id;f.tournamentId=c.tournamentId;f.userId=c.userId;f.versionId=c.versionId;f.artifactHash=c.artifactHash;f.sourceHash=c.sourceHash;f.failurePolicy=t.timeline.validationFailurePolicy().name();f.status="QUEUED";f.stepsJson=encode(emptySteps());f.historyJson="[]";f.createdAt=now;db.persist(f);db.flush();if(!now.isBefore(t.timeline.validationDeadline())){f.status="INFRA_ERROR";f.reason="VALIDATION_DEADLINE";f.finishedAt=now;}else enqueue(f);}
 @Transactional public void claimed(CodingJob j){var f=db.find(FinalValidation.class,j.finalValidationId,LockModeType.PESSIMISTIC_WRITE);if(f!=null&&Objects.equals(f.jobId,j.id)){f.status="RUNNING";}}
 @Transactional public void exhausted(CodingJob j){var f=db.find(FinalValidation.class,j.finalValidationId,LockModeType.PESSIMISTIC_WRITE);if(f!=null&&Objects.equals(f.jobId,j.id)){f.status="INFRA_ERROR";f.reason="WORKER_RECOVERY_EXHAUSTED";f.finishedAt=clock.instant();}}
 private boolean fenced(CodingQueueStore.Lease lease,FinalValidation f){var j=db.find(CodingJob.class,lease.id());return j!=null&&j.status.equals("RUNNING")&&Objects.equals(j.leaseToken,lease.token())&&Objects.equals(f.jobId,j.id);}
 @Transactional public boolean progress(CodingQueueStore.Lease lease,String stage,Map<String,String> completed){var f=db.find(FinalValidation.class,lease.finalValidationId(),LockModeType.PESSIMISTIC_WRITE);if(f==null||!fenced(lease,f))return false;var map=new LinkedHashMap<>(completed);map.put(stage,"RUNNING");f.stepsJson=encode(map);return true;}
 public record Context(Instant deadline,String failure){}
 @Transactional(readOnly=true) public Context preflight(CodingQueueStore.Lease lease){var f=db.find(FinalValidation.class,lease.finalValidationId());if(f==null||!fenced(lease,f))return new Context(clock.instant(),"STALE_JOB");var c=db.find(CodingFreeze.class,f.freezeId);var v=db.find(CodeVersion.class,f.versionId);var w=db.find(CodeWorkspace.class,v.workspaceId);String raw=(String)db.createNativeQuery("select structure_json from tournaments where id=:t").setParameter("t",f.tournamentId).getSingleResult();var details=new com.rpsbattle.tournament.persistence.TournamentDetailsConverter().convertToEntityAttribute(raw);var tl=details.timeline();String failure=null;
  if(tl==null||!clock.instant().isBefore(tl.validationDeadline()))failure="VALIDATION_DEADLINE";else if(!Set.of("REGISTRATION","CHECK_IN","READY","PAUSED","RECOVERY_REQUIRED").contains(db.createNativeQuery("select status from tournaments where id=:t").setParameter("t",f.tournamentId).getSingleResult().toString()))failure="TOURNAMENT_LOCKED";
  else if(!v.workspaceId.equals(lease.work().workspaceId())||!w.userId.equals(f.userId)||!w.tournamentId.equals(f.tournamentId)||!Objects.equals(f.artifactHash,v.artifactHash)||!Objects.equals(f.sourceHash,v.sourceHash))failure="ARTIFACT_CHANGED";
  else if(((Number)db.createNativeQuery("select count(*) from users where id=:u and status='ACTIVE'").setParameter("u",f.userId).getSingleResult()).intValue()!=1)failure="ACCOUNT_INACTIVE";
  else if(((Number)db.createNativeQuery("select count(*) from tournament_timeline_registrations where tournament_id=:t and user_id=:u and status='APPROVED'").setParameter("t",f.tournamentId).setParameter("u",f.userId).getSingleResult()).intValue()!=1)failure="REGISTRATION_NOT_APPROVED";
  else if(db.createQuery("select count(s) from BotSubmission s where s.tournamentId=:t and s.userId=:u and s.status='LOCKED'",Long.class).setParameter("t",f.tournamentId).setParameter("u",f.userId).getSingleResult()!=1)failure="SUBMISSION_NOT_LOCKED";
  var p=details.botPolicy();boolean imported=v.importedBotId!=null;if(failure==null&&(!p.allowedLanguages().contains(w.language)||imported&&p.submissionMode()==BotSubmissionMode.CODE_IN_PLATFORM_ONLY||!imported&&p.submissionMode()==BotSubmissionMode.PRE_UPLOADED_ONLY))failure="BOT_SUBMISSION_POLICY_MISMATCH";
  return new Context(tl==null?clock.instant():tl.validationDeadline(),failure);
 }
 @Transactional public void complete(CodingQueueStore.Lease lease,boolean passed,boolean infrastructure,String reason,Map<String,String> results){var f=db.find(FinalValidation.class,lease.finalValidationId(),LockModeType.PESSIMISTIC_WRITE);if(f==null||!fenced(lease,f))return;var j=db.find(CodingJob.class,lease.id(),LockModeType.PESSIMISTIC_WRITE);var context=preflight(lease);if(context.failure()!=null){passed=false;reason=context.failure();infrastructure=Set.of("VALIDATION_DEADLINE","STALE_JOB").contains(reason);}f.stepsJson=encode(results);f.status=passed?"PASSED":infrastructure?"INFRA_ERROR":"FAILED";f.reason=passed?null:reason;f.finishedAt=clock.instant();j.status=passed?"DONE":"FAILED";j.finishedAt=f.finishedAt;var history=history(f);history.add(Map.of("versionId",f.versionId.toString(),"status",f.status,"reason",Objects.toString(f.reason,""),"steps",Map.copyOf(results)));f.historyJson=encode(history);}
 @Transactional(readOnly=true) public List<UUID> unapplied(String t,int limit){return db.createQuery("select f.id from FinalValidation f where f.tournamentId=:t and f.appliedAt is null and f.status in ('PASSED','FAILED','INFRA_ERROR') order by f.createdAt,f.id",UUID.class).setParameter("t",UUID.fromString(t)).setMaxResults(limit).getResultList();}
 @Transactional public boolean fallback(Tournament t,UUID id){var f=require(t.id,id);if(!f.status.equals("FAILED")||!f.failurePolicy.equals("USE_LAST_VALID_VERSION")||!clock.instant().isBefore(t.timeline.validationDeadline()))return false;var c=db.find(CodingFreeze.class,f.freezeId);var v=db.find(CodeVersion.class,f.versionId);var choices=db.createQuery("select older from CodeVersion older,CodeWorkspace w where older.workspaceId=w.id and w.tournamentId=:t and w.userId=:u and older.createdAt<:created and older.createdAt<:cutoff and older.updatedAt<:cutoff and older.status in ('READY','SUBMITTED','LOCKED') and older.publicPassed=true and older.samplePassed=true and older.artifactHash is not null order by older.createdAt desc,older.id desc",CodeVersion.class).setParameter("t",f.tournamentId).setParameter("u",f.userId).setParameter("created",v.createdAt).setParameter("cutoff",c.codingCloseAt).setMaxResults(1).getResultList();if(choices.isEmpty())return false;var previous=choices.getFirst();f.versionId=previous.id;f.sourceHash=previous.sourceHash;f.artifactHash=previous.artifactHash;enqueue(f);return true;}
 public record Applied(UUID userId,UUID registrationId,boolean passed,String status){}
 @Transactional public Applied apply(Tournament t,UUID id){var f=require(t.id,id);if(f.appliedAt!=null)return null;var s=db.createQuery("select s from BotSubmission s where s.tournamentId=:t and s.userId=:u",BotSubmission.class).setParameter("t",f.tournamentId).setParameter("u",f.userId).getSingleResult();boolean passed=f.status.equals("PASSED");if(passed&&((Number)db.createNativeQuery("select count(*) from users where id=:u and status='ACTIVE'").setParameter("u",f.userId).getSingleResult()).intValue()!=1){passed=false;f.status="FAILED";f.reason="ACCOUNT_INACTIVE";}if(passed){var v=db.find(CodeVersion.class,f.versionId);s.versionId=v.id;s.artifactHash=f.artifactHash;s.status="LOCKED";v.status="LOCKED";v.publicPassed=true;v.samplePassed=true;v.hiddenPassed=true;v.executionBotId=s.executionBotId;}else if(f.status.equals("FAILED"))s.status="DISQUALIFIED";f.appliedAt=clock.instant();return new Applied(f.userId,s.registrationId,passed,f.status);}
 @Transactional public void retry(Tournament t,UUID id){var f=require(t.id,id);if(superseded(f)||!f.status.equals("INFRA_ERROR")||!clock.instant().isBefore(t.timeline.validationDeadline()))throw new AuthException("FINAL_RETRY_NOT_ALLOWED",409);enqueue(f);}
 @Transactional(readOnly=true) public Instant emergencyCutoff(String t,UUID user){return db.createQuery("select f.emergencyDeadline from FinalValidation f where f.tournamentId=:t and f.userId=:u and f.emergencyDeadline is not null order by f.emergencyDeadline desc",Instant.class).setParameter("t",UUID.fromString(t)).setParameter("u",user).setMaxResults(1).getResultStream().findFirst().orElse(null);}
 @Transactional(readOnly=true) public boolean emergencyOpen(String t,UUID user){var cutoff=emergencyCutoff(t,user);return cutoff!=null&&clock.instant().isBefore(cutoff);}
 @Transactional(readOnly=true) public int emergencyGrantCount(String t,UUID user){return (int)db.createQuery("select f from FinalValidation f where f.tournamentId=:t and f.userId=:u",FinalValidation.class).setParameter("t",UUID.fromString(t)).setParameter("u",user).getResultStream().filter(f->f.emergencyDeadline!=null||history(f).stream().anyMatch(e->e.get("emergencyDeadline")!=null&&!e.get("emergencyDeadline").toString().isBlank())).limit(100).count();}
 @Transactional(readOnly=true) public List<UUID> expiredEmergencies(String t,int limit){return db.createQuery("select f.userId from FinalValidation f where f.tournamentId=:t and f.emergencyDeadline<=:now and not exists(select c.id from CodingFreeze c where c.tournamentId=f.tournamentId and c.userId=f.userId and c.codingCloseAt=f.emergencyDeadline) order by f.emergencyDeadline,f.id",UUID.class).setParameter("t",UUID.fromString(t)).setParameter("now",clock.instant()).setMaxResults(limit).getResultList();}
 @Transactional public UUID grantEmergency(Tournament t,UUID id,UUID actor,String reason,Instant deadline){var f=require(t.id,id);Instant now=clock.instant();if(superseded(f)||f.appliedAt==null||!f.status.equals("FAILED")||!f.failurePolicy.equals("ALLOW_EMERGENCY_RESUBMISSION")||f.emergencyDeadline!=null||emergencyCutoff(t.id,f.userId)!=null||deadline==null||!deadline.isAfter(now)||!deadline.isBefore(t.timeline.validationDeadline()))throw new AuthException("EMERGENCY_NOT_ALLOWED",409);f.emergencyOpenAt=now;f.emergencyDeadline=deadline;f.emergencyActor=actor;f.emergencyReason=reason;var s=db.createQuery("select s from BotSubmission s where s.tournamentId=:t and s.userId=:u",BotSubmission.class).setParameter("t",f.tournamentId).setParameter("u",f.userId).getSingleResult();s.status="REJECTED";for(var w:db.createQuery("select w from CodeWorkspace w where w.tournamentId=:t and w.userId=:u",CodeWorkspace.class).setParameter("t",f.tournamentId).setParameter("u",f.userId).getResultList()){w.status="DRAFT";w.currentVersionId=null;w.touch();}db.createNativeQuery("insert into bot_submission_audit(id,tournament_id,user_id,action,version_id,reason,occurred_at) values(:id,:t,:u,'ALLOW-RESUBMIT',:v,:reason,:now)").setParameter("id",UUID.randomUUID()).setParameter("t",f.tournamentId).setParameter("u",actor).setParameter("v",s.versionId).setParameter("reason",reason).setParameter("now",now).executeUpdate();return f.userId;}
}
